fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only need to check parent nodes up to floor(n/2) - 1
    // because nodes after that are leaves and have no children.
    let last_parent = n / 2;

    for i in 0..last_parent {
        let left = 2 * i + 1;
        if left < n && a[i] > a[left] {
            return false;
        }
        let right = 2 * i + 2;
        if right < n && a[i] > a[right] {
            return false;
        }
    }
    true
}